--- frontends/platform-chrome/src/kite/Avatar.tsx (88 lines) ---
import type { ReactElement } from "react";

/**
 * Avatar — a neutral monogram avatar. NO faction ring (the participant
 * surface must not leak faction grouping — that is an instructor-only
 * affordance and is structurally absent here).
 *
 * The background color is DERIVED DETERMINISTICALLY from `seed` (the stable
 * character id), NOT from the character's `avatar_color`. avatar_color is
 * assigned from the faction palette server-side, so coloring avatars from it
 * would leak faction grouping to participants. A pure hash over a fixed
 * neutral palette gives a stable-per-profile, faction-uncorrelated color:
 * the same character id renders the same swatch everywhere (feed + profile),
 * and different ids spread across the palette.
 */
export interface AvatarProps {
  readonly displayName: string;
  /** Stable seed for the color hash — the character id. */
  readonly seed: string;
  /** Diameter in px. 40 in feed cards, 80 on the profile header. */
  readonly size?: number;
}

/**
 * Neutral, WCAG-AA-contrast-safe swatches. Each is dark enough that white
 * monogram text (text-cog-surface) clears 4.5:1 contrast at the avatar's
 * font weight, and none maps to any faction palette hue meaningfully (the
 * mapping is by id-hash, not faction).
 */
const PALETTE: readonly string[] = [
  // design-ratchet-allow: user-data — per-user avatar identity ramp. A user's identity colour is
  // DATA, not styling: it is persisted and rendered as an inline style on
  // user content, so it must be a literal string with no cog-* class to carry it.
  "#4B5563", // slate
  "#6B5B95", // muted violet
  "#3B6E8F", // steel blue
  "#2E7D6B", // teal green
  "#7A6A4F", // taupe
  "#8C5A6E", // mauve
  "#5C6BC0", // indigo
  "#4F7942", // moss
  "#9A6A3A", // bronze
  "#5D5D81", // dusk
  "#A05252", // brick
  "#3F7A8C", // ocean
];

/**
 * fnv1a — a small, deterministic 32-bit string hash (FNV-1a). Stable across
 * runs and platforms; used only to pick a palette index, never for security.
 */
function fnv1a(input: string): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    // 32-bit FNV prime multiply via shifts to stay in int range.
    hash = (hash + ((hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24))) >>> 0;
  }
  return hash >>> 0;
}

function colorForSeed(seed: string): string {
  return PALETTE[fnv1a(seed) % PALETTE.length];
}

export function Avatar({
  displayName,
  seed,
  size = 40,
}: AvatarProps): ReactElement {
  const monogram = (displayName.trim().charAt(0) || "?").toUpperCase();
  const bg = colorForSeed(seed);
  return (
    <span
      aria-hidden="true"
      className="inline-flex shrink-0 items-center justify-center rounded-pill font-semibold text-cog-surface"
      style={{
        width: size,
        height: size,
        fontSize: Math.round(size * 0.4),
        backgroundColor: bg,
      }}
    >
      {monogram}
    </span>
  );
}


--- frontends/platform-chrome/src/kite/ComposeBox.tsx (86 lines) ---
/**
 * ComposeBox — the post composer. 280-char counter that warns at 20 chars
 * remaining (cog-warning) and goes danger at 0 (cog-danger). The Post button
 * disables when the body is empty or over-limit; disabled state uses
 * bg + border (never opacity) per the design a11y rule.
 *
 * The optional `composerControls` slot lets a host MFE inject extra controls
 * into the bottom row (e.g. range-mfe's instructor-only controls). kite-mfe
 * passes nothing → the slot renders nothing, so its surface stays free of any
 * instructor affordance.
 */

import { useState, type ReactElement, type ReactNode } from "react";
import * as m from "../paraglide/messages";
import { KITE_PRIMARY_PILL } from "./kiteButtonClasses";

const MAX_CHARS = 280;
const WARN_AT = 20;

export interface ComposeBoxProps {
  readonly onSubmit: (body: string) => void | Promise<void>;
  readonly placeholder?: string;
  readonly submitLabel?: string;
  /** Optional content rendered above the textarea (e.g. quoted-post preview). */
  readonly above?: ReactNode;
  /** Disables the whole composer while a network submit is in flight. */
  readonly busy?: boolean;
  /** Optional controls injected into the bottom row (instructor-only host
   *  slot). Absent → nothing extra renders. */
  readonly composerControls?: ReactNode;
}

export function ComposeBox({
  onSubmit,
  placeholder,
  submitLabel,
  above,
  busy = false,
  composerControls,
}: ComposeBoxProps): ReactElement {
  const [body, setBody] = useState("");
  const trimmed = body.trim();
  const remaining = MAX_CHARS - body.length;
  const overLimit = remaining < 0;
  const canSubmit = trimmed.length > 0 && !overLimit && !busy;

  async function submit(): Promise<void> {
    if (!canSubmit) return;
    await onSubmit(trimmed);
    setBody("");
  }

  const counterClass = overLimit
    ? "text-cog-danger-500 dark:text-cog-danger-dark"
    : remaining <= WARN_AT
      ? "text-cog-warning"
      : "text-cog-text-tertiary";

  return (
    <div className="flex flex-col gap-cog-2 border-b border-cog-divider p-cog-4">
      {above}
      <textarea
        value={body}
        onChange={(e) => setBody(e.target.value)}
        placeholder={placeholder ?? m.kite_range_kite_compose_placeholder()}
        rows={2}
        className="w-full resize-none bg-transparent text-body-lg text-cog-text-primary placeholder:text-cog-text-tertiary focus:outline-none focus:ring-2 focus:ring-cog-focus"
      />
      <div className="flex items-center justify-end gap-cog-3">
        {composerControls}
        <span className={`text-body-sm ${counterClass}`} aria-live="polite">
          {m.kite_range_kite_compose_chars_remaining({ count: remaining })}
        </span>
        <button
          type="button"
          disabled={!canSubmit}
          onClick={submit}
          className={KITE_PRIMARY_PILL}
        >
          {submitLabel ?? m.kite_range_kite_compose_submit()}
        </button>
      </div>
    </div>
  );
}


--- frontends/platform-chrome/src/kite/FollowToggle.tsx (61 lines) ---
/**
 * FollowToggle — Follow (primary) / Following (secondary) button. When
 * already following, the label swaps to "Unfollow" (danger styling) on hover
 * so the destructive action is discoverable without being color-alone — the
 * text itself changes. aria-pressed carries the follow state for a11y.
 */

import { useState, type ReactElement } from "react";
import * as m from "../paraglide/messages";
import { KITE_PRIMARY_PILL } from "./kiteButtonClasses";

export interface FollowToggleProps {
  readonly following: boolean;
  readonly onToggle: (next: boolean) => void;
  readonly busy?: boolean;
}

export function FollowToggle({
  following,
  onToggle,
  busy = false,
}: FollowToggleProps): ReactElement {
  const [hover, setHover] = useState(false);

  if (!following) {
    return (
      <button
        type="button"
        aria-pressed={false}
        disabled={busy}
        onClick={() => onToggle(true)}
        className={KITE_PRIMARY_PILL}
      >
        {m.kite_range_kite_follow()}
      </button>
    );
  }

  // Following: secondary chip; hovering surfaces the destructive "Unfollow"
  // label (text changes — not color-only) styled with the danger border.
  return (
    <button
      type="button"
      aria-pressed={true}
      disabled={busy}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      onFocus={() => setHover(true)}
      onBlur={() => setHover(false)}
      onClick={() => onToggle(false)}
      className={
        hover
          ? "min-h-btn-sm rounded-pill border border-cog-danger-500 px-cog-4 text-body-md font-semibold text-cog-danger-500 focus:outline-none focus:ring-2 focus:ring-cog-focus dark:border-cog-danger-dark dark:text-cog-danger-dark"
          : "min-h-btn-sm rounded-pill border border-cog-border px-cog-4 text-body-md font-semibold text-cog-text-primary focus:outline-none focus:ring-2 focus:ring-cog-focus"
      }
    >
      {hover ? m.kite_range_kite_unfollow() : m.kite_range_kite_following()}
    </button>
  );
}


--- frontends/platform-chrome/src/kite/KiteAvatar.tsx (102 lines) ---
/**
 * KiteAvatar — the Kite-flavoured avatar (#1900). A non-empty `seed` renders
 * a deterministic DiceBear SVG entirely offline (`toDataUri()` + `<img>` — no
 * `dangerouslySetInnerHTML`, no XSS surface, air-gap safe, same pipeline as
 * range-mfe's ProfileAvatar). An empty `seed` falls back to the EXISTING
 * neutral monogram badge (`Avatar.tsx`), unchanged — that component is kept
 * as-is and delegated to here rather than duplicated, so the seed-hashed
 * palette lives in exactly one place.
 *
 * `style` resolves style prop → KiteAvatarStyleContext → DEFAULT_AVATAR_STYLE,
 * so a caller with no provider mounted (e.g. an isolated test, or a future
 * session-less surface) still renders correctly by passing `style` directly.
 *
 * CRITICAL (carried over from Avatar.tsx's doc comment): the seed must NEVER
 * be `avatar_color` or derived from it, and there is deliberately no
 * avatar_color/color prop on this component at all. avatar_color is assigned
 * from the faction palette server-side, so seeding or coloring from it would
 * leak faction grouping to participants. Callers must pass a genuinely
 * seed-only value (a real DiceBear `avatar_seed`, or "" to get the monogram
 * badge) — never the color.
 *
 * Decorative like its ProfileAvatar sibling: the adjacent name text (rendered
 * by the caller) carries the accessible identity, so the `<img>` gets
 * `alt=""` (implicit `role="presentation"`) rather than `aria-hidden` — the
 * latter would also hide it from `getByRole` queries.
 *
 * `seed` (the DiceBear render seed) and `monogramSeed` (the monogram
 * fallback's color-hash seed) are DELIBERATELY separate props (code review
 * finding, #1900). `seed` must stay empty-or-absent-render-seed only — never
 * substituted with a stable id — while the monogram badge's color hash still
 * needs a stable-per-character value to spread characters across its
 * palette; forwarding the empty `seed` to `Avatar` there would collapse
 * every seedless character onto the same swatch. `monogramSeed` defaults to
 * `seed` so a caller that only ever passes a real, non-empty `seed` (and
 * thus never hits the monogram path) is unaffected.
 */

import { type ReactElement, useMemo } from "react";

import { createAvatarDataUri, type AvatarStyle } from "../avatar/dicebearAvatar";
import { Avatar } from "./Avatar";
import { useKiteAvatarStyle } from "./KiteAvatarStyleContext";

export interface KiteAvatarProps {
  /** Used for the monogram's initial when falling back; never rendered as visible/accessible text for the DiceBear path. */
  readonly displayName: string;
  /** DiceBear render seed. Empty ⇒ monogram fallback (Avatar.tsx). NEVER avatar_color. */
  readonly seed: string;
  /**
   * Stable per-character id used ONLY for the monogram fallback's color
   * hash; never a DiceBear render seed, and never `avatar_color` — avatar_color
   * is assigned from the faction palette server-side, so seeding OR coloring
   * the monogram from it would leak faction grouping to participants, same as
   * `seed` above. Defaults to `seed` so a caller that only passes `seed`
   * renders unchanged.
   */
  readonly monogramSeed?: string;
  /** Best-effort gender bias for the character styles (lorelei/personas). */
  readonly gender?: string;
  /** Overrides the exercise-wide KiteAvatarStyleContext when set. */
  readonly style?: AvatarStyle;
  /** Diameter in px. Defaults to Avatar.tsx's existing default so call sites are unchanged. */
  readonly size?: number;
}

export function KiteAvatar({
  displayName,
  seed,
  monogramSeed = seed,
  gender,
  style,
  size = 40,
}: KiteAvatarProps): ReactElement {
  const contextStyle = useKiteAvatarStyle();
  const resolvedStyle = style ?? contextStyle;

  // DiceBear rendering is synchronous CPU work; memoize so a re-render of a
  // feed/profile list (filtering, hover, selection) doesn't re-generate an
  // unchanged avatar per row. Empty seed short-circuits to "" (monogram path
  // below) so no render work runs for the fallback case.
  const dataUri = useMemo(
    () => (seed === "" ? "" : createAvatarDataUri(seed, resolvedStyle, { gender, size })),
    [seed, resolvedStyle, gender, size],
  );

  if (seed === "") {
    return <Avatar displayName={displayName} seed={monogramSeed} size={size} />;
  }

  return (
    <img
      src={dataUri}
      alt=""
      width={size}
      height={size}
      className="shrink-0 rounded-pill"
    />
  );
}

export default KiteAvatar;


--- frontends/platform-chrome/src/kite/KiteAvatarStyleContext.tsx (65 lines) ---
/**
 * KiteAvatarStyleContext — the exercise-wide DiceBear avatar style for the
 * Kite surfaces (#1900). Mirrors range-mfe's AvatarStyleContext (see
 * frontends/range-mfe/src/context/AvatarStyleContext.tsx), but lives here in
 * platform-chrome/kite instead of range-mfe because kite-mfe runs OUTSIDE the
 * Keycloak shell and has no access to range-mfe's provider — both Kite
 * surfaces (the standalone kite-mfe app and range-mfe's in-shell clone) need
 * a provider they can each mount independently from the same
 * `GET /api/v1/kite/me`-shaped `exercise.avatar_style` payload.
 *
 * Every KiteAvatar reads the current exercise's avatar style through this
 * context instead of threading the prop through every route, so changing the
 * setting re-styles every Kite avatar at once.
 *
 * No live setter: unlike range-mfe's instructor-facing Settings picker, there
 * is no in-Kite UI that changes the style, so the provider only re-syncs from
 * the persisted `style` prop (e.g. a refetch of `/kite/me`) and exposes no
 * `setStyle`. Add one later if a caller needs to push a live update without a
 * refetch/remount.
 */

import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactElement,
  type ReactNode,
} from "react";

import { DEFAULT_AVATAR_STYLE, normalizeAvatarStyle, type AvatarStyle } from "../avatar/dicebearAvatar";

const KiteAvatarStyleContext = createContext<AvatarStyle | undefined>(undefined);

export interface KiteAvatarStyleProviderProps {
  /** The exercise's raw avatar_style (may be absent/empty — protojson zero-value). */
  readonly style: string | null | undefined;
  readonly children: ReactNode;
}

export function KiteAvatarStyleProvider({
  style,
  children,
}: KiteAvatarStyleProviderProps): ReactElement {
  const [current, setCurrent] = useState<AvatarStyle>(() => normalizeAvatarStyle(style));

  // Re-sync when the PERSISTED value changes (e.g. a refetch of /kite/me
  // after the instructor changes the setting, or navigating to a different
  // exercise's Kite surface).
  useEffect(() => {
    setCurrent(normalizeAvatarStyle(style));
  }, [style]);

  return (
    <KiteAvatarStyleContext.Provider value={current}>
      {children}
    </KiteAvatarStyleContext.Provider>
  );
}

/** Reads the current exercise's Kite avatar style; DEFAULT_AVATAR_STYLE outside any provider. */
export function useKiteAvatarStyle(): AvatarStyle {
  return useContext(KiteAvatarStyleContext) ?? DEFAULT_AVATAR_STYLE;
}


--- frontends/platform-chrome/src/kite/KiteLayout.tsx (76 lines) ---
/**
 * KiteLayout — the three-region X shell (Direction 3 Hybrid).
 *
 *   left nav 275px (icon+label: Home, Profile, Logout)
 *   center timeline 600px (children — tablist + compose + post list)
 *   right rail 350px (rightRail slot, defaults to TrendsEmptyState)
 *
 * DATA-AGNOSTIC: nav targets are injected (homeHref/profileHref) and logout
 * is an injected callback — no coupling to any MFE's api client or session
 * hook. Logical properties only (ms/me, border-s/e, text-start) so the ar-AE
 * RTL flip is automatic. Radius tokens are BARE (rounded-*) per the range-mfe
 * gotcha — cog- is colors/spacing only.
 */

import type { ReactElement, ReactNode } from "react";
import { Link } from "react-router-dom";
import { House, User, LogOut } from "@omnicore-platform/ui/icons";
import * as m from "../paraglide/messages";
import { TrendsEmptyState } from "./TrendsEmptyState";

export interface KiteLayoutProps {
  readonly homeHref: string;
  readonly profileHref: string;
  readonly onLogout: () => void;
  /** Right-rail content; defaults to the shared TrendsEmptyState. */
  readonly rightRail?: ReactNode;
  readonly children: ReactNode;
}

export function KiteLayout({
  homeHref,
  profileHref,
  onLogout,
  rightRail,
  children,
}: KiteLayoutProps): ReactElement {
  const navItemClass =
    "flex min-h-btn items-center gap-cog-3 rounded-pill px-cog-4 text-body-lg text-cog-text-primary hover:bg-cog-surface-muted focus:outline-none focus:ring-2 focus:ring-cog-focus";

  return (
    <div className="flex min-h-screen justify-center bg-cog-canvas text-cog-text-primary">
      {/* design-ratchet-allow: no-token-axis */}
      <div className="flex w-full max-w-[1265px]">
        {/* Left nav */}
        <nav
          aria-label={m.kite_range_kite_app_name()}
          className="hidden w-cog-kite-rail shrink-0 flex-col gap-cog-2 border-e border-cog-divider p-cog-4 md:flex"
        >
          <Link to={homeHref} className={navItemClass}>
            <House className="h-cog-5 w-cog-5" aria-hidden="true" />
            <span>{m.kite_range_kite_nav_home()}</span>
          </Link>
          <Link to={profileHref} className={navItemClass}>
            <User className="h-cog-5 w-cog-5" aria-hidden="true" />
            <span>{m.kite_range_kite_nav_profile()}</span>
          </Link>
          <button type="button" onClick={onLogout} className={navItemClass}>
            <LogOut className="h-cog-5 w-cog-5" aria-hidden="true" />
            <span>{m.kite_range_kite_logout()}</span>
          </button>
        </nav>

        {/* Center timeline */}
        <div className="w-full min-w-cog-0 max-w-cog-kite-column border-e border-cog-divider">
          {children}
        </div>

        {/* Right rail */}
        <aside className="hidden w-cog-kite-aside shrink-0 flex-col p-cog-4 lg:flex">
          {rightRail ?? <TrendsEmptyState />}
        </aside>
      </div>
    </div>
  );
}


--- frontends/platform-chrome/src/kite/PostCard.tsx (196 lines) ---
/**
 * PostCard — the shared, route/data-agnostic feed card. Built for the
 * participant surface: there is NO faction ring, NO Synthetic badge, NO
 * AudienceChip, NO viewerRole baked in. The instructor surface is injected
 * (and OPTIONAL) via the `overlay` render-prop — when no overlay is passed,
 * nothing instructor-y renders, so kite-mfe's path stays structurally free of an
 * instructor surface.
 *
 * Route targets are injected via the `links` builder (KiteLinkBuilder): kite-mfe
 * builds /k/... and the range clone builds /range/exercises/:id/kite/... . The
 * card renders the exact href the builder returns and never constructs a
 * route itself.
 *
 * The avatar is seeded by author_avatar_seed — NEVER avatar_color — so it
 * never leaks faction grouping, and it re-styles with the exercise-wide
 * KiteAvatarStyleContext. An absent seed renders the monogram badge rather
 * than substituting character_id, matching range-mfe's ProfileAvatar and the
 * in-range Kite surfaces so one character never renders two different faces
 * across the two clones (#1900). The monogram fallback's color hash is a
 * SEPARATE concern from the render seed: it is keyed off `character_id` via
 * `monogramSeed` so seedless characters still spread across the monogram's
 * 12-color palette instead of collapsing onto one swatch.
 */

import type { ReactElement, ReactNode } from "react";
import { Link } from "react-router-dom";
import {
  MessageCircle,
  Heart,
  Newspaper,
  ChevronRight,
} from "@omnicore-platform/ui/icons";
import * as m from "../paraglide/messages";
import { KiteAvatar } from "./KiteAvatar";
import { VerifiedBadge } from "./VerifiedBadge";
import { RelativeTime } from "./RelativeTime";
import { RepostMenu } from "./RepostMenu";
import { QuotedPostBlock } from "./QuotedPostBlock";
import { KITE_ACTION_ROW, KITE_FOCUS_RING } from "./kiteButtonClasses";
import type { KiteLinkBuilder, KitePostView } from "./types";

export interface PostCardProps {
  readonly post: KitePostView;
  readonly links: KiteLinkBuilder;
  readonly onLikeToggle: (post: KitePostView) => void;
  readonly onRepost: (post: KitePostView) => void;
  /**
   * Quote capability seam. OPTIONAL: when omitted (the in-shell range clone,
   * which has no quote route), the RepostMenu hides its Quote item — no dead
   * button. kite-mfe passes it for the real quote-compose flow.
   */
  readonly onQuote?: (post: KitePostView) => void;
  /** Optional instructor overlay. Absent → nothing instructor-y renders. */
  readonly overlay?: (post: KitePostView) => ReactNode;
}

export function PostCard({
  post,
  links,
  onLikeToggle,
  onRepost,
  onQuote,
  overlay,
}: PostCardProps): ReactElement {
  const profileHref = links.profileHref(post.author_username);
  const detailHref = links.postHref(post.id);

  const actionClass = `${KITE_ACTION_ROW} text-cog-text-tertiary ${KITE_FOCUS_RING}`;

  return (
    <article className="flex gap-cog-3 border-b border-cog-divider p-cog-4">
      <Link to={profileHref} aria-label={post.author_display_name}>
        <KiteAvatar
          displayName={post.author_display_name}
          seed={post.author_avatar_seed ?? ""}
          monogramSeed={post.character_id}
          gender={post.author_gender}
          size={40}
        />
      </Link>
      <div className="min-w-cog-0 flex-1">
        <div className="flex items-center gap-cog-2">
          <Link
            to={profileHref}
            className="text-body-md font-semibold text-cog-text-primary hover:underline"
          >
            {post.author_display_name}
          </Link>
          {post.author_verified && <VerifiedBadge />}
          <span className="text-body-sm text-cog-text-tertiary">
            {m.kite_range_kite_handle({ handle: post.author_username })}
          </span>
          <span aria-hidden="true" className="text-cog-text-tertiary">
            {"·"}
          </span>
          <RelativeTime iso={post.created_at} />
        </div>

        {overlay?.(post)}

        <Link
          to={detailHref}
          className="mt-cog-1 block whitespace-pre-wrap break-words text-body-md text-cog-text-primary"
        >
          {post.body}
        </Link>

        {/* Outlet auto-post source article. A SIBLING of the body Link above,
            so a click here never falls through to the post-detail route.
            In-app targets (range-mfe, same router) use a router Link — a
            same-tab full page load would drop the whole exercise shell.
            Cross-app targets (kite-mfe, a separate deployed app) use a plain
            <a target="_blank"> instead, since that router can't serve the
            other app's route at all. */}
        {post.source_baseline_article_id !== "" &&
          (() => {
            const href = links.baselineArticleHref(
              post.source_baseline_article_id,
            );
            const className = `mt-cog-2 flex items-center justify-between gap-cog-2 rounded-lg border border-cog-divider bg-cog-surface-subtle p-cog-3 text-cog-text-primary hover:bg-cog-surface-muted ${KITE_FOCUS_RING}`;
            const inner = (
              <>
                <span className="flex min-w-cog-0 items-center gap-cog-2">
                  <Newspaper
                    className="h-cog-4 w-cog-4 shrink-0 text-cog-text-secondary"
                    aria-hidden="true"
                  />
                  <span className="truncate text-body-md font-medium">
                    {m.range_kite_view_article_in_range()}
                  </span>
                </span>
                <ChevronRight
                  className="h-cog-4 w-cog-4 shrink-0 text-cog-text-tertiary"
                  aria-hidden="true"
                />
              </>
            );
            return links.baselineArticleIsInApp ? (
              <Link to={href} className={className}>
                {inner}
              </Link>
            ) : (
              <a
                href={href}
                target="_blank"
                rel="noopener noreferrer"
                className={className}
              >
                {inner}
              </a>
            );
          })()}

        {post.quoted_post && (
