/**
 * QuoteComposer — the shared quote-post modal. It is DATA-AGNOSTIC: the
 * network call is lifted out. The host MFE passes `onSubmit(body)` (which
 * wires its own quotePost + feed-prepend); this component just renders the
 * modal with the embedded read-only quoted-post preview and forwards the
 * typed body, then closes.
 *
 * Failure contract: when `onSubmit` REJECTS, the dialog stays open and a
 * danger toast (via the shared `useToast()` store) surfaces the error so
 * the user can retry; the next submit attempt is unaffected by the prior
 * toast (it auto-dismisses on its own timer). A resolving onSubmit keeps
 * the original auto-close.
 */

import { useState, type ReactElement } from "react";
import { X } from "@omnicore-platform/ui/icons";
import * as m from "../paraglide/messages";
import { useToast } from "../toast";
import { ComposeBox } from "./ComposeBox";
import { QuotedPostBlock } from "./QuotedPostBlock";
import type { QuotedPostView, KiteLinkBuilder, KitePostView } from "./types";

export interface QuoteComposerProps {
  readonly quoted: KitePostView;
  readonly links: KiteLinkBuilder;
  readonly onClose: () => void;
  readonly onSubmit: (body: string) => void | Promise<void>;
}

export function QuoteComposer({
  quoted,
  links,
  onClose,
  onSubmit,
}: QuoteComposerProps): ReactElement {
  const [busy, setBusy] = useState(false);
  const toast = useToast();

  // QuotedPostBlock renders the compact QuotedPostView subset; build it from
  // the full KitePostView (a structural superset carrying the same fields).
  // author_avatar_seed/author_gender (#1900) MUST be copied through too — an
  // omission here would leave the composer's embedded preview rendering the
  // monogram badge for an author whose feed card (and the eventual quote
  // post) shows a real DiceBear avatar.
  const preview: QuotedPostView = {
    id: quoted.id,
    character_id: quoted.character_id,
    author_username: quoted.author_username,
    author_display_name: quoted.author_display_name,
    author_avatar_color: quoted.author_avatar_color,
    author_avatar_seed: quoted.author_avatar_seed,
    author_gender: quoted.author_gender,
    body: quoted.body,
    created_at: quoted.created_at,
  };

  async function submit(body: string): Promise<void> {
    setBusy(true);
    try {
      await onSubmit(body);
      onClose();
    } catch {
      // Keep the dialog open so the user can retry; surface the error via
      // a toast (reaches whichever host MFE's <ToastHost /> is mounted).
      toast.danger(m.kite_range_kite_quote_error());
    } finally {
      setBusy(false);
    }
  }

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label={m.kite_range_kite_quote()}
      className="fixed inset-cog-0 z-20 flex items-start justify-center bg-cog-canvas/70 p-cog-5"
    >
      <div className="w-full max-w-cog-kite-column rounded-xl border border-cog-divider bg-cog-surface shadow-cog-e4">
        <div className="flex justify-end p-cog-2">
          <button
            type="button"
            onClick={onClose}
            aria-label={m.kite_range_kite_post_detail_back()}
            className="min-h-tap min-w-tap rounded-pill text-body-lg text-cog-text-tertiary hover:bg-cog-surface-muted focus:outline-none focus:ring-2 focus:ring-cog-focus"
          >
            <X className="h-cog-4-5 w-cog-4-5" aria-hidden="true" />
          </button>
        </div>
        <ComposeBox
          onSubmit={submit}
          busy={busy}
          placeholder={m.kite_range_kite_quote_placeholder()}
          submitLabel={m.kite_range_kite_quote_submit()}
          above={<QuotedPostBlock post={preview} links={links} preview />}
        />
      </div>
    </div>
  );
}


