import type { ReactElement } from "react";
import * as m from "../paraglide/messages";
import { useFormatDate } from "../i18n/useFormatDate";

/**
 * RelativeTime — renders a <time> element with the X-style compact timestamp
 * label, self-localized via the platform's active locale:
 *
 *   - under a minute  → the localized "now" (kite_range_kite_time_now)
 *   - under an hour   → "3m"
 *   - under a day     → "2h"
 *   - a day or older  → locale-aware month-day via Intl ("Jun 5"), with the
 *     year appended for prior years ("Jun 5, 2025")
 *
 * The machine-readable ISO timestamp lives in dateTime. `now` is injectable
 * for deterministic tests. The optional className lets X-faithful surfaces
 * restyle the label (default keeps the cog-token treatment used by the
 * shared PostCard).
 */
export interface RelativeTimeProps {
  readonly iso: string;
  readonly now?: number;
  readonly className?: string;
}

export function RelativeTime({
  iso,
  now,
  className,
}: RelativeTimeProps): ReactElement {
  // Both date-form formatters are created unconditionally (hooks rule); the
  // same-year check picks which one labels the post.
  const monthDay = useFormatDate({ month: "short", day: "numeric" });
  const monthDayYear = useFormatDate({
    month: "short",
    day: "numeric",
    year: "numeric",
  });
  const then = Date.parse(iso);
  const reference = now ?? Date.now();
  let label: string;
  if (Number.isNaN(then)) {
    label = "";
  } else {
    const seconds = Math.max(0, Math.floor((reference - then) / 1000));
    if (seconds < 60) {
      label = m.kite_range_kite_time_now();
    } else if (seconds < 3600) {
      label = `${Math.floor(seconds / 60)}m`;
    } else if (seconds < 86400) {
      label = `${Math.floor(seconds / 3600)}h`;
    } else {
      const posted = new Date(then);
      const sameYear =
        posted.getFullYear() === new Date(reference).getFullYear();
      label = sameYear
        ? monthDay.format(posted)
        : monthDayYear.format(posted);
    }
  }
  return (
    <time
      dateTime={iso}
      className={className ?? "text-body-sm text-cog-text-tertiary"}
    >
      {label}
    </time>
  );
}


