/**
 * Shared VIEW types for the cross-MFE Kite-feed presentational components.
 *
 * These are decoupled from any one MFE's BFF client (kite-mfe's api/kite.ts defines
 * a richer KitePost that is a structural SUPERSET of KitePostView — so kite-mfe can
 * pass its KitePost wherever a KitePostView is expected). Keep field names byte-
 * identical to the BFF/api shape so structural typing holds.
 *
 * Route targets are NOT baked in: the host MFE injects a KiteLinkBuilder so the
 * same card renders /k/... in kite-mfe and /range/exercises/:id/kite/... in the
 * range clone.
 */

/**
 * QuotedPostView — the compact embedded subset shown inside a quote post (and
 * the quote-composer preview). NOT a full post: no counts, no liked flag.
 */
export interface QuotedPostView {
  readonly id: string;
  readonly character_id: string;
  readonly author_username: string;
  readonly author_display_name: string;
  readonly author_avatar_color: string;
  /**
   * Real DiceBear render seed for the author's avatar (#1900). OPTIONAL: an
   * older BFF omits it (`omitempty`) — an absent seed renders the monogram
   * badge, never a character_id substitute (see PostCard's doc for why).
   * NEVER author_avatar_color; see KitePostView's field doc for why.
   */
  readonly author_avatar_seed?: string;
  /** Best-effort gender bias for the author's avatar (lorelei/personas styles only). OPTIONAL, same reason as author_avatar_seed. */
  readonly author_gender?: string;
  readonly body: string;
  readonly created_at: string;
}

/**
 * KitePostView — the fields the shared feed components render. The avatar color
 * derives from `character_id` (the seed), NEVER from author_avatar_color, so
