import type { ReactElement } from "react";

/**
 * Avatar — a neutral monogram avatar. NO faction ring (the participant
 * surface must not leak faction grouping — that is an instructor-only
 * affordance and is structurally absent here).
 *
 * The background color is DERIVED DETERMINISTICALLY from `seed` (the stable
 * character id), NOT from the character's `avatar_color`. avatar_color is
 * assigned from the faction palette server-side, so coloring avatars from it
 * would leak faction grouping to participants. A pure hash over a fixed
 * neutral palette gives a stable-per-profile, faction-uncorrelated color:
 * the same character id renders the same swatch everywhere (feed + profile),
 * and different ids spread across the palette.
 */
export interface AvatarProps {
  readonly displayName: string;
  /** Stable seed for the color hash — the character id. */
  readonly seed: string;
  /** Diameter in px. 40 in feed cards, 80 on the profile header. */
  readonly size?: number;
}

/**
 * Neutral, WCAG-AA-contrast-safe swatches. Each is dark enough that white
 * monogram text (text-cog-surface) clears 4.5:1 contrast at the avatar's
 * font weight, and none maps to any faction palette hue meaningfully (the
 * mapping is by id-hash, not faction).
 */
const PALETTE: readonly string[] = [
  // design-ratchet-allow: user-data — per-user avatar identity ramp. A user's identity colour is
  // DATA, not styling: it is persisted and rendered as an inline style on
  // user content, so it must be a literal string with no cog-* class to carry it.
  "#4B5563", // slate
  "#6B5B95", // muted violet
  "#3B6E8F", // steel blue
  "#2E7D6B", // teal green
  "#7A6A4F", // taupe
  "#8C5A6E", // mauve
  "#5C6BC0", // indigo
  "#4F7942", // moss
  "#9A6A3A", // bronze
  "#5D5D81", // dusk
  "#A05252", // brick
  "#3F7A8C", // ocean
];

/**
 * fnv1a — a small, deterministic 32-bit string hash (FNV-1a). Stable across
 * runs and platforms; used only to pick a palette index, never for security.
 */
function fnv1a(input: string): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    // 32-bit FNV prime multiply via shifts to stay in int range.
    hash = (hash + ((hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24))) >>> 0;
  }
  return hash >>> 0;
}

function colorForSeed(seed: string): string {
  return PALETTE[fnv1a(seed) % PALETTE.length];
}

export function Avatar({
  displayName,
  seed,
  size = 40,
}: AvatarProps): ReactElement {
  const monogram = (displayName.trim().charAt(0) || "?").toUpperCase();
  const bg = colorForSeed(seed);
  return (
    <span
      aria-hidden="true"
      className="inline-flex shrink-0 items-center justify-center rounded-pill font-semibold text-cog-surface"
      style={{
        width: size,
        height: size,
        fontSize: Math.round(size * 0.4),
        backgroundColor: bg,
      }}
    >
      {monogram}
    </span>
  );
}


