/**
 * ComposeBox — the post composer. 280-char counter that warns at 20 chars
 * remaining (cog-warning) and goes danger at 0 (cog-danger). The Post button
 * disables when the body is empty or over-limit; disabled state uses
 * bg + border (never opacity) per the design a11y rule.
 *
 * The optional `composerControls` slot lets a host MFE inject extra controls
 * into the bottom row (e.g. range-mfe's instructor-only controls). kite-mfe
 * passes nothing → the slot renders nothing, so its surface stays free of any
 * instructor affordance.
 */

import { useState, type ReactElement, type ReactNode } from "react";
import * as m from "../paraglide/messages";
import { KITE_PRIMARY_PILL } from "./kiteButtonClasses";

const MAX_CHARS = 280;
const WARN_AT = 20;

export interface ComposeBoxProps {
  readonly onSubmit: (body: string) => void | Promise<void>;
  readonly placeholder?: string;
  readonly submitLabel?: string;
  /** Optional content rendered above the textarea (e.g. quoted-post preview). */
  readonly above?: ReactNode;
  /** Disables the whole composer while a network submit is in flight. */
  readonly busy?: boolean;
  /** Optional controls injected into the bottom row (instructor-only host
   *  slot). Absent → nothing extra renders. */
  readonly composerControls?: ReactNode;
}

export function ComposeBox({
  onSubmit,
  placeholder,
  submitLabel,
  above,
  busy = false,
  composerControls,
}: ComposeBoxProps): ReactElement {
  const [body, setBody] = useState("");
  const trimmed = body.trim();
  const remaining = MAX_CHARS - body.length;
  const overLimit = remaining < 0;
  const canSubmit = trimmed.length > 0 && !overLimit && !busy;

  async function submit(): Promise<void> {
    if (!canSubmit) return;
    await onSubmit(trimmed);
    setBody("");
  }

  const counterClass = overLimit
    ? "text-cog-danger-500 dark:text-cog-danger-dark"
    : remaining <= WARN_AT
      ? "text-cog-warning"
      : "text-cog-text-tertiary";

  return (
    <div className="flex flex-col gap-cog-2 border-b border-cog-divider p-cog-4">
      {above}
      <textarea
        value={body}
        onChange={(e) => setBody(e.target.value)}
        placeholder={placeholder ?? m.kite_range_kite_compose_placeholder()}
        rows={2}
        className="w-full resize-none bg-transparent text-body-lg text-cog-text-primary placeholder:text-cog-text-tertiary focus:outline-none focus:ring-2 focus:ring-cog-focus"
      />
      <div className="flex items-center justify-end gap-cog-3">
        {composerControls}
        <span className={`text-body-sm ${counterClass}`} aria-live="polite">
          {m.kite_range_kite_compose_chars_remaining({ count: remaining })}
        </span>
        <button
          type="button"
          disabled={!canSubmit}
          onClick={submit}
          className={KITE_PRIMARY_PILL}
        >
          {submitLabel ?? m.kite_range_kite_compose_submit()}
        </button>
      </div>
    </div>
  );
}


