/**
 * FollowToggle — Follow (primary) / Following (secondary) button. When
 * already following, the label swaps to "Unfollow" (danger styling) on hover
 * so the destructive action is discoverable without being color-alone — the
 * text itself changes. aria-pressed carries the follow state for a11y.
 */

import { useState, type ReactElement } from "react";
import * as m from "../paraglide/messages";
import { KITE_PRIMARY_PILL } from "./kiteButtonClasses";

export interface FollowToggleProps {
  readonly following: boolean;
  readonly onToggle: (next: boolean) => void;
  readonly busy?: boolean;
}

export function FollowToggle({
  following,
  onToggle,
  busy = false,
}: FollowToggleProps): ReactElement {
  const [hover, setHover] = useState(false);

  if (!following) {
    return (
      <button
        type="button"
        aria-pressed={false}
        disabled={busy}
        onClick={() => onToggle(true)}
        className={KITE_PRIMARY_PILL}
      >
        {m.kite_range_kite_follow()}
      </button>
    );
  }

  // Following: secondary chip; hovering surfaces the destructive "Unfollow"
  // label (text changes — not color-only) styled with the danger border.
  return (
    <button
      type="button"
      aria-pressed={true}
      disabled={busy}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      onFocus={() => setHover(true)}
      onBlur={() => setHover(false)}
      onClick={() => onToggle(false)}
      className={
        hover
          ? "min-h-btn-sm rounded-pill border border-cog-danger-500 px-cog-4 text-body-md font-semibold text-cog-danger-500 focus:outline-none focus:ring-2 focus:ring-cog-focus dark:border-cog-danger-dark dark:text-cog-danger-dark"
          : "min-h-btn-sm rounded-pill border border-cog-border px-cog-4 text-body-md font-semibold text-cog-text-primary focus:outline-none focus:ring-2 focus:ring-cog-focus"
      }
    >
      {hover ? m.kite_range_kite_unfollow() : m.kite_range_kite_following()}
    </button>
  );
}


