/**
 * KiteAvatar — the Kite-flavoured avatar (#1900). A non-empty `seed` renders
 * a deterministic DiceBear SVG entirely offline (`toDataUri()` + `<img>` — no
 * `dangerouslySetInnerHTML`, no XSS surface, air-gap safe, same pipeline as
 * range-mfe's ProfileAvatar). An empty `seed` falls back to the EXISTING
 * neutral monogram badge (`Avatar.tsx`), unchanged — that component is kept
 * as-is and delegated to here rather than duplicated, so the seed-hashed
 * palette lives in exactly one place.
 *
 * `style` resolves style prop → KiteAvatarStyleContext → DEFAULT_AVATAR_STYLE,
 * so a caller with no provider mounted (e.g. an isolated test, or a future
 * session-less surface) still renders correctly by passing `style` directly.
 *
 * CRITICAL (carried over from Avatar.tsx's doc comment): the seed must NEVER
 * be `avatar_color` or derived from it, and there is deliberately no
 * avatar_color/color prop on this component at all. avatar_color is assigned
 * from the faction palette server-side, so seeding or coloring from it would
 * leak faction grouping to participants. Callers must pass a genuinely
 * seed-only value (a real DiceBear `avatar_seed`, or "" to get the monogram
 * badge) — never the color.
 *
 * Decorative like its ProfileAvatar sibling: the adjacent name text (rendered
 * by the caller) carries the accessible identity, so the `<img>` gets
 * `alt=""` (implicit `role="presentation"`) rather than `aria-hidden` — the
 * latter would also hide it from `getByRole` queries.
 *
 * `seed` (the DiceBear render seed) and `monogramSeed` (the monogram
 * fallback's color-hash seed) are DELIBERATELY separate props (code review
 * finding, #1900). `seed` must stay empty-or-absent-render-seed only — never
 * substituted with a stable id — while the monogram badge's color hash still
 * needs a stable-per-character value to spread characters across its
 * palette; forwarding the empty `seed` to `Avatar` there would collapse
 * every seedless character onto the same swatch. `monogramSeed` defaults to
 * `seed` so a caller that only ever passes a real, non-empty `seed` (and
 * thus never hits the monogram path) is unaffected.
 */

import { type ReactElement, useMemo } from "react";

import { createAvatarDataUri, type AvatarStyle } from "../avatar/dicebearAvatar";
import { Avatar } from "./Avatar";
import { useKiteAvatarStyle } from "./KiteAvatarStyleContext";

export interface KiteAvatarProps {
  /** Used for the monogram's initial when falling back; never rendered as visible/accessible text for the DiceBear path. */
  readonly displayName: string;
  /** DiceBear render seed. Empty ⇒ monogram fallback (Avatar.tsx). NEVER avatar_color. */
  readonly seed: string;
  /**
   * Stable per-character id used ONLY for the monogram fallback's color
   * hash; never a DiceBear render seed, and never `avatar_color` — avatar_color
   * is assigned from the faction palette server-side, so seeding OR coloring
   * the monogram from it would leak faction grouping to participants, same as
   * `seed` above. Defaults to `seed` so a caller that only passes `seed`
   * renders unchanged.
   */
  readonly monogramSeed?: string;
  /** Best-effort gender bias for the character styles (lorelei/personas). */
  readonly gender?: string;
  /** Overrides the exercise-wide KiteAvatarStyleContext when set. */
  readonly style?: AvatarStyle;
  /** Diameter in px. Defaults to Avatar.tsx's existing default so call sites are unchanged. */
  readonly size?: number;
}

export function KiteAvatar({
  displayName,
  seed,
  monogramSeed = seed,
  gender,
  style,
  size = 40,
}: KiteAvatarProps): ReactElement {
  const contextStyle = useKiteAvatarStyle();
  const resolvedStyle = style ?? contextStyle;

  // DiceBear rendering is synchronous CPU work; memoize so a re-render of a
  // feed/profile list (filtering, hover, selection) doesn't re-generate an
  // unchanged avatar per row. Empty seed short-circuits to "" (monogram path
  // below) so no render work runs for the fallback case.
  const dataUri = useMemo(
    () => (seed === "" ? "" : createAvatarDataUri(seed, resolvedStyle, { gender, size })),
    [seed, resolvedStyle, gender, size],
  );

  if (seed === "") {
    return <Avatar displayName={displayName} seed={monogramSeed} size={size} />;
  }

  return (
    <img
      src={dataUri}
      alt=""
      width={size}
      height={size}
      className="shrink-0 rounded-pill"
    />
  );
}

export default KiteAvatar;


