/**
 * KiteAvatarStyleContext — the exercise-wide DiceBear avatar style for the
 * Kite surfaces (#1900). Mirrors range-mfe's AvatarStyleContext (see
 * frontends/range-mfe/src/context/AvatarStyleContext.tsx), but lives here in
 * platform-chrome/kite instead of range-mfe because kite-mfe runs OUTSIDE the
 * Keycloak shell and has no access to range-mfe's provider — both Kite
 * surfaces (the standalone kite-mfe app and range-mfe's in-shell clone) need
 * a provider they can each mount independently from the same
 * `GET /api/v1/kite/me`-shaped `exercise.avatar_style` payload.
 *
 * Every KiteAvatar reads the current exercise's avatar style through this
 * context instead of threading the prop through every route, so changing the
 * setting re-styles every Kite avatar at once.
 *
 * No live setter: unlike range-mfe's instructor-facing Settings picker, there
 * is no in-Kite UI that changes the style, so the provider only re-syncs from
 * the persisted `style` prop (e.g. a refetch of `/kite/me`) and exposes no
 * `setStyle`. Add one later if a caller needs to push a live update without a
 * refetch/remount.
 */

import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactElement,
  type ReactNode,
} from "react";

import { DEFAULT_AVATAR_STYLE, normalizeAvatarStyle, type AvatarStyle } from "../avatar/dicebearAvatar";

const KiteAvatarStyleContext = createContext<AvatarStyle | undefined>(undefined);

export interface KiteAvatarStyleProviderProps {
  /** The exercise's raw avatar_style (may be absent/empty — protojson zero-value). */
  readonly style: string | null | undefined;
  readonly children: ReactNode;
}

export function KiteAvatarStyleProvider({
  style,
  children,
}: KiteAvatarStyleProviderProps): ReactElement {
  const [current, setCurrent] = useState<AvatarStyle>(() => normalizeAvatarStyle(style));

  // Re-sync when the PERSISTED value changes (e.g. a refetch of /kite/me
  // after the instructor changes the setting, or navigating to a different
  // exercise's Kite surface).
  useEffect(() => {
    setCurrent(normalizeAvatarStyle(style));
  }, [style]);

  return (
    <KiteAvatarStyleContext.Provider value={current}>
      {children}
    </KiteAvatarStyleContext.Provider>
  );
}

/** Reads the current exercise's Kite avatar style; DEFAULT_AVATAR_STYLE outside any provider. */
export function useKiteAvatarStyle(): AvatarStyle {
  return useContext(KiteAvatarStyleContext) ?? DEFAULT_AVATAR_STYLE;
}


