  onLikeToggle,
  onRepost,
  onQuote,
  overlay,
}: PostCardProps): ReactElement {
  const profileHref = links.profileHref(post.author_username);
  const detailHref = links.postHref(post.id);

  const actionClass = `${KITE_ACTION_ROW} text-cog-text-tertiary ${KITE_FOCUS_RING}`;

  return (
    <article className="flex gap-cog-3 border-b border-cog-divider p-cog-4">
