          >
            {post.author_display_name}
          </Link>
          {post.author_verified && <VerifiedBadge />}
          <span className="text-body-sm text-cog-text-tertiary">
            {m.kite_range_kite_handle({ handle: post.author_username })}
          </span>
          <span aria-hidden="true" className="text-cog-text-tertiary">
            {"·"}
          </span>
          <RelativeTime iso={post.created_at} />
        </div>

        {overlay?.(post)}

        <Link
          to={detailHref}
          className="mt-cog-1 block whitespace-pre-wrap break-words text-body-md text-cog-text-primary"
        >
          {post.body}
        </Link>

        {/* Outlet auto-post source article. A SIBLING of the body Link above,
            so a click here never falls through to the post-detail route.
            In-app targets (range-mfe, same router) use a router Link — a
            same-tab full page load would drop the whole exercise shell.
            Cross-app targets (kite-mfe, a separate deployed app) use a plain
            <a target="_blank"> instead, since that router can't serve the
            other app's route at all. */}
        {post.source_baseline_article_id !== "" &&
          (() => {
            const href = links.baselineArticleHref(
              post.source_baseline_article_id,
            );
            const className = `mt-cog-2 flex items-center justify-between gap-cog-2 rounded-lg border border-cog-divider bg-cog-surface-subtle p-cog-3 text-cog-text-primary hover:bg-cog-surface-muted ${KITE_FOCUS_RING}`;
            const inner = (
              <>
                <span className="flex min-w-cog-0 items-center gap-cog-2">
                  <Newspaper
                    className="h-cog-4 w-cog-4 shrink-0 text-cog-text-secondary"
                    aria-hidden="true"
                  />
                  <span className="truncate text-body-md font-medium">
                    {m.range_kite_view_article_in_range()}
                  </span>
                </span>
                <ChevronRight
                  className="h-cog-4 w-cog-4 shrink-0 text-cog-text-tertiary"
                  aria-hidden="true"
                />
              </>
            );
            return links.baselineArticleIsInApp ? (
              <Link to={href} className={className}>
                {inner}
              </Link>
            ) : (
              <a
                href={href}
                target="_blank"
                rel="noopener noreferrer"
                className={className}
              >
                {inner}
              </a>
            );
          })()}

        {post.quoted_post && (
          <QuotedPostBlock post={post.quoted_post} links={links} />
        )}

        <div className="mt-cog-2 flex items-center justify-between pe-cog-6">
          <Link
            to={detailHref}
            className={actionClass}
            aria-label={m.kite_range_kite_action_reply()}
          >
            <MessageCircle className="h-cog-4 w-cog-4" aria-hidden="true" />
            <span>{m.kite_range_kite_action_reply()}</span>
            <span aria-hidden="true">{post.reply_count}</span>
          </Link>

          <RepostMenu
            repostCount={post.repost_count}
            onRepost={() => onRepost(post)}
            onQuote={onQuote ? () => onQuote(post) : undefined}
          />

          <button
            type="button"
            aria-pressed={post.liked}
            onClick={() => onLikeToggle(post)}
            className={`${actionClass} ${post.liked ? "text-kite-like" : "hover:text-kite-like"}`}
          >
