import { useEffect, useRef, useState, type ReactElement } from "react";
import { Repeat2, Quote } from "@omnicore-platform/ui/icons";
import * as m from "../paraglide/messages";
import { KITE_ACTION_ROW, KITE_FOCUS_RING } from "./kiteButtonClasses";

/**
 * RepostMenu — the repost affordance. The trigger icon opens a role="menu"
 * with Repost (immediate) and — when the host supplies a quote capability —
 * Quote (opens the QuoteComposer via onQuote). Closes on Escape, outside
 * click, or item activation.
 *
 * Two presentation seams are opt-in so the default rendering (what kite-mfe
 * consumes) is untouched: `hideLabel` for an icon + count trigger, and `tone`
 * for the kite-* palette used by the simulated-site surfaces.
 */
export interface RepostMenuProps {
  readonly repostCount: number;
  readonly onRepost: () => void;
  /**
   * Quote capability seam. OPTIONAL: a host without a quote route (the in-shell
   * range clone) omits it, and the menu hides the Quote item rather than
   * rendering a dead button. kite-mfe passes it (real quote via QuoteComposer).
   */
  readonly onQuote?: () => void;
  /**
   * Whether the viewer has reposted this post (the host's optimistic state).
   * Announced via aria-pressed on the trigger — never color-alone — with a
   * green tint as the visual signal. Defaults to false.
   */
  readonly reposted?: boolean;
  /**
   * Drop the visible "Repost" text from the trigger, leaving icon + count, and
   * carry the accessible name on aria-label instead. OPT-IN: the kite-mfe
   * consumer omits it and keeps the labelled trigger unchanged.
   */
  readonly hideLabel?: boolean;
  /**
   * Which palette the trigger tints itself from. "cog" (the default, and what
   * kite-mfe gets) uses cog-green-600 / cog-text-tertiary; "kite" uses
   * kite-boost / kite-text2 for the simulated-site surfaces, where a cog-*
   * token would be off-palette.
   */
  readonly tone?: "cog" | "kite";
}

export function RepostMenu({
  repostCount,
  onRepost,
  onQuote,
  reposted = false,
  hideLabel = false,
  tone = "cog",
}: RepostMenuProps): ReactElement {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    function onDocClick(e: MouseEvent): void {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setOpen(false);
      }
    }
    function onKey(e: KeyboardEvent): void {
      if (e.key === "Escape") setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onDocClick);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  const itemClass =
    "flex w-full min-h-btn items-center gap-cog-2 px-cog-4 text-start text-body-md text-cog-text-primary hover:bg-cog-surface-muted focus:outline-none focus:ring-2 focus:ring-cog-focus";

  // The tint sits on the BUTTON, so the icon and the count both inherit the
  // boosted colour at rest (color-alone is never the only signal — aria-pressed
  // carries the state).
  const restTint =
    tone === "kite"
      ? reposted
        ? "text-kite-boost"
        : "text-kite-text2"
      : reposted
        ? "text-cog-green-600"
        : "text-cog-text-tertiary";
  const hoverTint =
    tone === "kite" ? "hover:text-kite-boost" : "hover:text-cog-green-600";

  return (
    <div ref={ref} className="relative">
      <button
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-pressed={reposted}
        aria-label={hideLabel ? m.kite_range_kite_action_repost() : undefined}
        onClick={() => setOpen((v) => !v)}
        className={`${KITE_ACTION_ROW} ${restTint} ${hoverTint} ${KITE_FOCUS_RING}`}
      >
        <Repeat2 className="h-cog-4 w-cog-4" aria-hidden="true" />
        {hideLabel ? null : <span>{m.kite_range_kite_action_repost()}</span>}
        <span aria-hidden="true">{repostCount}</span>
      </button>
      {open && (
        <div
          role="menu"
          aria-label={m.kite_range_kite_repost_menu_label()}
          // design-ratchet-allow: no-token-axis
          className="absolute z-10 mt-cog-1 w-[180px] overflow-hidden rounded-md border border-cog-divider bg-cog-surface py-cog-1 shadow-cog-e3"
        >
          <button
            type="button"
            role="menuitem"
            onClick={() => {
              setOpen(false);
              onRepost();
            }}
            className={itemClass}
          >
            <Repeat2 className="h-cog-4 w-cog-4" aria-hidden="true" />
            {m.kite_range_kite_repost_now()}
          </button>
          {onQuote && (
            <button
              type="button"
              role="menuitem"
              onClick={() => {
                setOpen(false);
                onQuote();
              }}
              className={itemClass}
            >
              <Quote className="h-cog-4 w-cog-4" aria-hidden="true" />
              {m.kite_range_kite_quote()}
            </button>
          )}
        </div>
      )}
    </div>
  );
}


