/**
 * Public barrel for the shared Kite-feed presentational components.
 *
 * These are route/data-agnostic, prop-driven components extracted from kite-mfe
 * so both the standalone participant app (kite-mfe) and the range clone surface
 * can consume one polished implementation. Route targets are injected via
 * KiteLinkBuilder; instructor affordances are injected via optional overlay/slot
 * render-props (absent → structurally no instructor surface).
 */

export { Avatar, type AvatarProps } from "./Avatar";
export { KiteAvatar, type KiteAvatarProps } from "./KiteAvatar";
export {
  KiteAvatarStyleProvider,
  useKiteAvatarStyle,
  type KiteAvatarStyleProviderProps,
} from "./KiteAvatarStyleContext";
export { VerifiedBadge } from "./VerifiedBadge";
export { RelativeTime, type RelativeTimeProps } from "./RelativeTime";
