/**
 * Shared VIEW types for the cross-MFE Kite-feed presentational components.
 *
 * These are decoupled from any one MFE's BFF client (kite-mfe's api/kite.ts defines
 * a richer KitePost that is a structural SUPERSET of KitePostView — so kite-mfe can
 * pass its KitePost wherever a KitePostView is expected). Keep field names byte-
 * identical to the BFF/api shape so structural typing holds.
 *
 * Route targets are NOT baked in: the host MFE injects a KiteLinkBuilder so the
 * same card renders /k/... in kite-mfe and /range/exercises/:id/kite/... in the
 * range clone.
 */

/**
 * QuotedPostView — the compact embedded subset shown inside a quote post (and
 * the quote-composer preview). NOT a full post: no counts, no liked flag.
 */
export interface QuotedPostView {
  readonly id: string;
  readonly character_id: string;
  readonly author_username: string;
  readonly author_display_name: string;
  readonly author_avatar_color: string;
  /**
   * Real DiceBear render seed for the author's avatar (#1900). OPTIONAL: an
   * older BFF omits it (`omitempty`) — an absent seed renders the monogram
   * badge, never a character_id substitute (see PostCard's doc for why).
   * NEVER author_avatar_color; see KitePostView's field doc for why.
   */
  readonly author_avatar_seed?: string;
  /** Best-effort gender bias for the author's avatar (lorelei/personas styles only). OPTIONAL, same reason as author_avatar_seed. */
  readonly author_gender?: string;
  readonly body: string;
  readonly created_at: string;
}

/**
 * KitePostView — the fields the shared feed components render. The avatar color
 * derives from `character_id` (the seed), NEVER from author_avatar_color, so
 * the participant surface never leaks faction grouping.
 *
 * `author_verified` (#1854 Step 18) marks an outlet-authored post so PostCard
 * can render the verified badge beside the author's name. It carries no color
 * of its own and never substitutes for the avatar-color anti-leak rule above.
 */
export interface KitePostView {
  readonly id: string;
  readonly character_id: string;
  readonly body: string;
  readonly created_at: string;
  readonly like_count: number;
  readonly repost_count: number;
  readonly reply_count: number;
  readonly liked: boolean;
  readonly author_username: string;
  readonly author_display_name: string;
  readonly author_avatar_color: string;
  /**
   * Real DiceBear render seed for the author's avatar (#1900). OPTIONAL: an
   * older BFF omits it (`omitempty`) — an absent seed renders the monogram
   * badge, never a character_id substitute.
   * NEVER author_avatar_color, for the same faction-leak reason as above.
   */
  readonly author_avatar_seed?: string;
  /** Best-effort gender bias for the author's avatar (lorelei/personas styles only). OPTIONAL, same reason as author_avatar_seed. */
  readonly author_gender?: string;
  readonly author_verified: boolean;
  /**
   * Id of the baseline article this post was auto-generated from. Empty string
   * for every hand- or AI-authored post; non-empty only on outlet auto-posts,
   * where the card renders its own link to the in-app article page. The raw
   * external URL is deliberately NOT on the wire — the participant reads the
   * ingested article inside Range, not the live web.
   */
  readonly source_baseline_article_id: string;
  readonly quoted_post: QuotedPostView | null;
}

/**
 * KiteCharacterView — the character fields the shared profile components render.
 * The avatar color derives from `id` (the seed), NEVER from avatar_color, so
 * the participant surface never leaks faction grouping.
 */
export interface KiteCharacterView {
  readonly id: string;
  readonly handle: string;
  readonly display_name: string;
  readonly avatar_color: string;
  /**
   * Real DiceBear render seed for this character's avatar (#1900). OPTIONAL:
   * an older BFF omits it (`omitempty`) — an absent seed renders
   * the monogram badge, never an `id` substitute (see PostCard's module doc for
   * why). NEVER avatar_color, for the same faction-leak reason as above.
   */
  readonly avatar_seed?: string;
  /** Best-effort gender bias for the avatar (lorelei/personas styles only). OPTIONAL, same reason as avatar_seed. */
  readonly gender?: string;
  readonly bio: string;
  readonly location?: string;
  readonly verified?: boolean;
  readonly following_count?: number;
  readonly followers_count?: number;
  readonly post_count?: number;
  readonly is_following?: boolean;
}

/**
 * KiteLinkBuilder — route-builder injected by the host MFE. kite-mfe builds
 * /k/{exercise}/... links; the range clone builds /range/exercises/:id/kite/...
 * links. The shared components render the exact href each builder returns and
 * never construct a route themselves.
 */
export interface KiteLinkBuilder {
  readonly profileHref: (username: string) => string;
  readonly postHref: (postId: string) => string;
  /**
   * The baseline-article page for an outlet auto-post's source article. This
   * one target lives OUTSIDE the feed's own route subtree. In the range clone
   * it's still the SAME app/router (relative path under RangeLayout), so the
   * card must navigate with a router Link to avoid a full-page reload that
   * drops the exercise shell. In kite-mfe it's a genuinely separate deployed
   * app, so this is an absolute cross-origin URL instead.
   */
  readonly baselineArticleHref: (articleId: string) => string;
  /**
   * Whether baselineArticleHref points at a route inside THIS app's own
   * router (true — render a router Link, in-place navigation) or a separate
   * deployed app (false — render a plain <a target="_blank">, since a
   * same-tab plain <a> to a same-origin SPA route would still force a full
   * reload and lose all in-memory app state).
   */
  readonly baselineArticleIsInApp: boolean;
}



